import { describe, expect, it } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import Assets from '../../assets.json';

// The six celebration sounds are generated by scripts/gen-sfx.mjs; these tests check the files it wrote (real, short, quiet), that they are registered
// for playSfx, and that each one is played from the place it is meant for.
const NEW_SOUNDS = ['level_up', 'forge_success', 'forge_rare', 'refine_fail', 'drop_rare', 'drop_unique'] as const;
const root = join(__dirname, '..', '..', '..');

function readWav(file: string): { seconds: number; peak: number; rate: number; channels: number; bits: number } {
  const b = readFileSync(file);
  expect(b.toString('ascii', 0, 4)).toBe('RIFF');
  expect(b.toString('ascii', 8, 12)).toBe('WAVE');
  const channels = b.readUInt16LE(22);
  const rate = b.readUInt32LE(24);
  const bits = b.readUInt16LE(34);
  const bytes = b.readUInt32LE(40);
  let peak = 0;
  for (let i = 44; i < 44 + bytes; i += 2) peak = Math.max(peak, Math.abs(b.readInt16LE(i)) / 32768);
  return { seconds: bytes / 2 / channels / rate, peak, rate, channels, bits };
}

describe('celebration sounds', () => {
  it('are registered in assets.json and exist on disk', () => {
    for (const key of NEW_SOUNDS) {
      const entry = (Assets.sfx as Record<string, { url: string }>)[key];
      expect(entry, key).toBeDefined();
      expect(entry.url).toBe(`/assets/sfx/${key}.wav`);
    }
  });

  it('are valid 16-bit PCM, under a second, and quiet', () => {
    for (const key of NEW_SOUNDS) {
      const wav = readWav(join(root, 'public', 'assets', 'sfx', `${key}.wav`));
      expect(wav.bits, key).toBe(16);
      expect(wav.channels, key).toBe(1);
      expect(wav.seconds, key).toBeGreaterThan(0.2);
      expect(wav.seconds, key).toBeLessThanOrEqual(1);
      expect(wav.peak, key).toBeGreaterThan(0.1);
      expect(wav.peak, key).toBeLessThanOrEqual(0.3);
    }
  });

  it('are played where they belong (and only through playSfx, which respects mute)', () => {
    const read = (p: string) => readFileSync(join(root, 'src', p), 'utf8');
    const app = read('App.tsx');
    expect(app).toContain("playSfx('level_up')");
    expect(app).toContain("'forge_rare' : 'forge_success'");
    expect(app).toContain("playSfx('refine_fail')");
    expect(read('components/HuntRewardModal.tsx')).toContain("playSfx('drop_unique')");
    expect(read('components/HuntRewardModal.tsx')).toContain("playSfx('drop_rare')");
    expect(read('components/WelcomeBackModal.tsx')).toContain("playSfx('drop_unique')");
    expect(read('components/WelcomeBackModal.tsx')).toContain("playSfx('drop_rare')");
  });

  it('the reveal glow switches itself off under prefers-reduced-motion', () => {
    const css = readFileSync(join(root, 'src', 'round11.css'), 'utf8');
    const reduced = css.slice(css.lastIndexOf('@media (prefers-reduced-motion: reduce)'));
    expect(reduced).toContain('.reveal');
    expect(reduced).toContain('animation: none');
  });
});
